I use playwright to "проверить баннер cookies", async ({ page }) => {
                const consentButton = page.locator(CookieBanner_1.CookieBanner.acceptButton).first();
                try {
                    await consentButton.waitFor({ state: 'visible', timeout: COOKIE_BANNER_TIMEOUT_MS });
                    bannerVisible = true;
                }
                catch (error) {
                    const isTimeoutError = error instanceof Error && error.name === 'TimeoutError';
                    if (!isTimeoutError) {
                        throw error;
                    }
                }
            }

I use playwright to "перейти на страницу удаления аккаунта", async ({ page }) => {
        const deleteAccountLink = page.locator(Header_1.Header.deleteAccountLinkSelector).first();
        await deleteAccountLink.waitFor({ state: 'visible', timeout: 10000 });
        await deleteAccountLink.scrollIntoViewIfNeeded();
        await Promise.all([
            page.waitForURL(/\/delete_account(?:[/?#]|$)/, { timeout: 20000 }),
            deleteAccountLink.click({ force: true })
        ]);
    }
